// Local review preparation only: no network calls and no Gmail changes.
const START = 1759273200000;
function collect(part, out) {
  if (!part || part.filename) return;
  if (part.mimeType === 'message/rfc822') return;
  if (['text/plain','text/html'].includes(part.mimeType)) {
    const contentType = (part.headers || []).find(h => h.name.toLowerCase() === 'content-type')?.value || '';
    const charset = /charset=["']?([^;"'\s]+)/i.exec(contentType)?.[1]?.toLowerCase() || 'utf-8';
    if (!['utf-8','utf8','us-ascii','ascii'].includes(charset)) out.warnings.push('Unsupported charset: ' + charset);
    if (part.body?.data) {
      const text = Buffer.from(part.body.data.replace(/-/g,'+').replace(/_/g,'/'),'base64').toString('utf8');
      out[part.mimeType === 'text/plain' ? 'plain' : 'html'].push(text);
    } else if (part.body?.attachmentId) out.warnings.push('Body requires separate attachment retrieval');
  }
  for (const child of part.parts || []) collect(child, out);
}
function htmlText(html) {
  return html.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,' ').replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi,' ').replace(/<br\s*\/?\s*>|<\/(p|div|li|tr)>/gi,'\n').replace(/<[^>]*>/g,' ').replace(/&nbsp;/gi,' ').replace(/&amp;/gi,'&').replace(/&lt;/gi,'<').replace(/&gt;/gi,'>').replace(/&quot;/gi,'"').replace(/&#39;/g,"'").replace(/&#(\d+);/g,(_,n)=>Number(n)<=0x10ffff?String.fromCodePoint(Number(n)):' ').replace(/[ \t]+/g,' ').replace(/\n\s*\n/g,'\n\n').trim();
}
function csvText(v) { return typeof v === "string" && /^[\s]*[=+@-]/.test(v) ? "'" + v : v; }
return $input.all().map((item,index) => {
  const m = item.json;
  const header = name => (m.payload?.headers || []).filter(h=>h.name.toLowerCase()===name).map(h=>h.value).join(' | ');
  const body = {plain:[],html:[],warnings:[]}; collect(m.payload,body);
  const text = body.plain.length ? body.plain.join('\n\n') : htmlText(body.html.join('\n'));
  if (!body.plain.length && body.html.length) body.warnings.push('HTML converted to approximate review text; verify original');
  if (!text) body.warnings.push('No readable body extracted');
  const scope = Number(m.internalDate) >= START;
  const signalText = header('subject') + '\n' + text;
  const hints = [];
  if (/not (?:be )?(?:progressing|proceeding|moving forward)|unsuccessful|regret to inform|not been selected|other candidates|unfortunately[\s\S]{0,120}application/i.test(signalText)) hints.push('rejection');
  if (/interview (?:invitation|scheduled)|invite you to (?:an? )?interview|schedule (?:an? |your )?interview/i.test(signalText)) hints.push('interview');
  if (/application (?:has been |was )?received|received your application|thank you for (?:your application|applying)/i.test(signalText)) hints.push('confirmation');
  return {json:{reviewerDecision:"",reviewerNotes:"",reviewedAt:"",gmailMessageId:m.id,threadId:m.threadId,subject:header('subject'),from:header('from'),date:header('date'),internalDate:m.internalDate,inHistoricalWindow:scope,existingLabels:m.labelIds || [],reviewStatus:scope?'pending_manual_review':'outside_date_window',candidateSignals:hints.join(', ') || 'none',classification:'unconfirmed',reviewText:text,extractionWarnings:body.warnings.join('; '),note:'Signals may match quotations or mixed outcomes. Human review required. No labels applied.'},pairedItem:{item:index}};
}).map(item => { for (const key of ["subject","from","date","reviewText","extractionWarnings"]) item.json[key] = csvText(item.json[key]); return item; });
